 "content": "from collections import Counter
from itertools import permutations


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find rectangular outline objects by color and bounding box.
    frames = []
    for color in set(v for row in grid for v in row if v != 0):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                     if r in (r0,r1) or c in (c0,c1)}
        if all(grid[r][c] == color for r,c in perimeter):
            frames.append((color, r0, r1, c0, c1))
    frame_colors = {f[0] for f in frames}
    noise_counts = Counter(v for row in grid for v in row if v not in (0,) and v not in frame_colors)
    # Scattered colors encode the checkerboard fill; match their occurrence counts
    # to the number of checkerboard cells in each frame's interior.
    colors = list(noise_counts)
    if frames and len(colors) >= len(frames):
        best = None
        for chosen in permutations(colors, len(frames)):
            score = 0
            for (_,r0,r1,c0,c1), col in zip(frames, chosen):
                n = sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1)
                        if (r-r0-1 + c-c0-1) % 2 == 0)
                score += abs(noise_counts[col] - n)
            if best is None or score < best[0]:
                best = (score, chosen)
        assignments = dict(zip(frames, best[1]))
    else:
        assignments = {}
    out = [[0]*w for _ in range(h)]
    for frame in frames:
        border, r0, r1, c0, c1 = frame
        fill = assignments.get(frame, 0)
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    out[r][c] = border
                elif (r-r0-1 + c-c0-1) % 2 == 0:
                    out[r][c] = fill
    return out
